import{_ as a,o as i,c as s,a0 as t}from"./chunks/framework.CNoGN0p1.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"setup/installation.md","filePath":"setup/installation.md"}'),n={name:"setup/installation.md"};function l(o,e,r,h,d,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Phenoblend is available as prepackaged installers for macOS, Windows, and Linux. Download the latest version from the <a href="https://github.com/p2gx/phenoblend/releases" target="_blank" rel="noreferrer">Releases</a> page.</p><h2 id="installing-on-macos" tabindex="-1">Installing on macOS <a class="header-anchor" href="#installing-on-macos" aria-label="Permalink to &quot;Installing on macOS&quot;">​</a></h2><blockquote><p><strong>File to download:</strong> <code>phenoblend_&lt;version&gt;_aarch64.dmg</code><br> This is the macOS installer for Apple Silicon (M1/M2/M3/M4 Macs)</p></blockquote><p>Because this application is open-source and distributed for free, it is not signed or notarized by Apple. macOS will warn you the first time you try to open it. Here&#39;s how to install:</p><ol><li>Download the <code>.dmg</code> file from the <a href="https://github.com/p2gx/phenoblend/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Open the DMG and drag the app into your Applications folder</li><li>When you try to open it, macOS will show the message:<br><em>&quot;&#39;phenoblend&#39; is an app downloaded from the Internet. Are you sure you want to open it?&quot;</em></li></ol><p>If you confirm, the app will be started. From now one you can open phenoblend like any other application (e.g., using the Spotlight searchbar).</p><h2 id="installing-on-windows" tabindex="-1">Installing on Windows <a class="header-anchor" href="#installing-on-windows" aria-label="Permalink to &quot;Installing on Windows&quot;">​</a></h2><blockquote><p><strong>File to download:</strong> <code>phenoblend_&lt;version&gt;_x64_en-US.msi</code><br> Windows installer (MSI format)</p></blockquote><ol><li>Download the <code>.msi</code> installer from the <a href="https://github.com/p2gx/phenoblend/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Double-click to start the installer</li><li>If Windows shows a blue SmartScreen dialog saying:<br><em>&quot;Windows protected your PC&quot;</em></li><li>Click <strong>&quot;More info&quot;</strong> → <strong>&quot;Run anyway&quot;</strong></li></ol><blockquote><p><strong>Note:</strong> Windows shows this for unsigned apps from new developers. Once you install and run it, the warning will not reappear.</p></blockquote><h2 id="installing-on-linux" tabindex="-1">Installing on Linux <a class="header-anchor" href="#installing-on-linux" aria-label="Permalink to &quot;Installing on Linux&quot;">​</a></h2><h3 id="debian-ubuntu-recommended" tabindex="-1">Debian/Ubuntu (recommended) <a class="header-anchor" href="#debian-ubuntu-recommended" aria-label="Permalink to &quot;Debian/Ubuntu (recommended)&quot;">​</a></h3><blockquote><p><strong>File to download:</strong> <code>phenoblend_&lt;version&gt;_amd64.deb</code><br> Debian/Ubuntu package</p></blockquote><ol><li>Download the <code>.deb</code> package from the <a href="https://github.com/p2gx/phenoblend/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Install using:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./phenoblend_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_amd64.deb</span></span></code></pre></div><p>Or using dpkg:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenoblend_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_amd64.deb</span></span></code></pre></div><h3 id="other-linux-distributions" tabindex="-1">Other Linux Distributions <a class="header-anchor" href="#other-linux-distributions" aria-label="Permalink to &quot;Other Linux Distributions&quot;">​</a></h3><blockquote><p><strong>File to download:</strong> <code>phenoblend_&lt;version&gt;_amd64.AppImage</code><br> Universal Linux application (no installation needed)</p></blockquote><ol><li>Download the <code>.AppImage</code> file from the <a href="https://github.com/p2gx/phenoblend/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Make it executable:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenoblend_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_amd64.AppImage</span></span></code></pre></div><ol start="3"><li>Run it:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./phenoblend_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;version&gt;_amd64.AppImage</span></span></code></pre></div><p><strong>Note for Arch-based distributions (e.g. EndeavourOS, Manjaro, etc.):</strong> The AppImage may not build/run correctly due to <code>linuxdeploy</code> compatibility issues. Use the <code>.deb</code> package instead (installable via <code>debtap</code>), or build from source and run the binary directly at <code>./src-tauri/target/release/phenoblend</code>.</p><h3 id="troubleshooting-on-linux" tabindex="-1">Troubleshooting on Linux <a class="header-anchor" href="#troubleshooting-on-linux" aria-label="Permalink to &quot;Troubleshooting on Linux&quot;">​</a></h3><h4 id="crash-on-launch-failed-to-create-gbm-buffer-hybrid-gpu-wayland" tabindex="-1">Crash on launch: <code>Failed to create GBM buffer</code> (hybrid GPU / Wayland) <a class="header-anchor" href="#crash-on-launch-failed-to-create-gbm-buffer-hybrid-gpu-wayland" aria-label="Permalink to &quot;Crash on launch: `Failed to create GBM buffer` (hybrid GPU / Wayland)&quot;">​</a></h4><p>It seems that the Tauri/wry rendering stack on Linux goes through WebKit2GTK, which by default attempts GPU-accelerated compositing via EGL and GBM. On hybrid GPU systems with NVIDIA drivers under Wayland, GBM buffer allocation can fail because the NVIDIA proprietary driver&#39;s GBM support is incomplete or incompatible with how WebKit2GTK requests buffers. The workaround is to disable WebKit2GTK GPU compositing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WEBKIT_DISABLE_COMPOSITING_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./src-tauri/target/release/phenoblend</span></span></code></pre></div>',29)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
